<?php
require_once __DIR__.'/config.php';require_login();$dept=trim($_GET['department']??'');$status=trim($_GET['status']??'');$deps=$db->query("SELECT DISTINCT department FROM employees WHERE department IS NOT NULL AND department<>'' ORDER BY department");$sql='SELECT employee_no,first_name,middle_name,last_name,department,position_title,employment_status,date_hired,email,phone FROM employees WHERE 1=1';if($dept!=='')$sql.=' AND department=?';if($status!=='')$sql.=' AND employment_status=?';$sql.=' ORDER BY department,last_name,first_name';$s=$db->prepare($sql);if($dept!==''&&$status!=='')$s->bind_param('ss',$dept,$status);elseif($dept!=='')$s->bind_param('s',$dept);elseif($status!=='')$s->bind_param('s',$status);$s->execute();$rows=$s->get_result();
page_header('Reports');echo '<h1>Employee reports</h1><div class="card no-print"><form method="get" class="form-grid"><div><label>Department</label><select name="department"><option value="">All departments</option>';while($d=$deps->fetch_assoc())echo '<option '.($dept===$d['department']?'selected':'').' value="'.h($d['department']).'">'.h($d['department']).'</option>';echo '</select></div><div><label>Status</label><select name="status"><option value="">All statuses</option>';foreach(['Permanent','Temporary','Contractual','Casual','Job Order','Contract of Service','Resigned','Retired','Separated'] as $v)echo '<option '.($status===$v?'selected':'').' value="'.h($v).'">'.h($v).'</option>';echo '</select></div><div class="actions" style="align-self:end"><button>Generate</button><button type="button" class="muted-btn" onclick="window.print()">Print / Save PDF</button></div></form></div><div class="card"><h2>Employee listing</h2><p>Generated '.date('Y-m-d H:i').' · Rows: '.$rows->num_rows.'</p><div class="table-wrap"><table><tr><th>Employee No.</th><th>Name</th><th>Department</th><th>Position</th><th>Status</th><th>Date hired</th><th>Contact</th></tr>';while($e=$rows->fetch_assoc())echo '<tr><td>'.h($e['employee_no']).'</td><td>'.h($e['last_name'].', '.$e['first_name'].' '.$e['middle_name']).'</td><td>'.h($e['department']).'</td><td>'.h($e['position_title']).'</td><td>'.h($e['employment_status']).'</td><td>'.h($e['date_hired']).'</td><td>'.h($e['email']).'<br>'.h($e['phone']).'</td></tr>';echo '</table></div></div>';page_footer();